use reverse_engineering::analysis::FunctionInfo;
use reverse_engineering::decompiler::{lift_function,lift_functions_with_imports,recover_function_signatures,structure_function_with_cfg,CGenerator,CGeneratorConfig,Optimizer,OptimizationLevel};
use reverse_engineering::disasm::{ControlFlowGraph,Instruction,X86Disassembler};
fn info(name:&str, bytes:&[u8],addr:u64)->(FunctionInfo,ControlFlowGraph){let ins=X86Disassembler::new_x64().disassemble(bytes,addr).unwrap();let cfg=ControlFlowGraph::from_x86(ins.clone());(FunctionInfo{name:name.into(),address:addr,size:bytes.len(),instructions:ins.into_iter().map(Instruction::X86).collect(),is_import:false,is_export:false},cfg)}
fn emit(name:&str,bytes:&[u8]) {let (i,cfg)=info(name,bytes,0x1000);let mut fs=vec![lift_function(&i)];structure_function_with_cfg(&mut fs[0],&cfg);recover_function_signatures(&mut fs,&[i],"PE/EXE","x64");let mut g=CGenerator::new(CGeneratorConfig::default());println!("// {name}\n{}",g.generate_function(&fs[0]));Optimizer::new(OptimizationLevel::Aggressive).optimize_function(&mut fs[0]);println!("// {name} optimized\n{}",g.generate_function(&fs[0]));}
fn main(){emit("flags_gap",&[0x83,0xf9,0,0x90,0x74,6,0xb8,1,0,0,0,0xc3,0x31,0xc0,0xc3]);emit("looping",&[0xb8,0,0,0,0,0xff,0xc0,0xff,0xc9,0x75,0xfa,0x89,0xc0,0xc3]);emit("memory_partial",&[0xc7,0x45,0xf8,0x44,0x33,0x22,0x11,0xc6,0x45,0xf8,0x55,0x8b,0x45,0xf8,0xc3]);let (caller,cfg)=info("caller",&[0xb9,5,0,0,0,0xe8,0xf6,0x0f,0,0,0x83,0xc0,1,0xc3],0x1000);let (callee,cfg2)=info("callee",&[0x8b,0xc1,0xc3],0x2000);let infos=vec![caller,callee];let mut fs=lift_functions_with_imports(&infos,&[]);structure_function_with_cfg(&mut fs[0],&cfg);structure_function_with_cfg(&mut fs[1],&cfg2);recover_function_signatures(&mut fs,&infos,"PE/EXE","x64");let mut g=CGenerator::new(CGeneratorConfig::default());for f in fs {println!("{}",g.generate_function(&f));}}
